@props(['id', 'maxWidth'])

@php
$id = $id ?? md5($attributes->wire('model'));

$maxWidth = [
    'sm' => 'sm:max-w-sm',
    'md' => 'sm:max-w-md',
    'lg' => 'sm:max-w-lg',
    'xl' => 'sm:max-w-xl',
    '2xl' => 'sm:max-w-2xl',
][$maxWidth ?? '2xl'];
@endphp

<div
    x-data="{
        {{-- Livewire 3 has no ".defer" on an entangle: with it "show" was undefined and no dialog ever opened (R-49). --}}
        show: @entangle($attributes->wire('model')),
        opener: null,
        focusables() {
            // All focusable element types...
            let selector = 'a, button, input:not([type=\'hidden\']), textarea, select, details, [tabindex]:not([tabindex=\'-1\'])'

            return [...$el.querySelectorAll(selector)]
                // All non-disabled elements...
                .filter(el => ! el.hasAttribute('disabled'))
        },
        firstFocusable() { return this.focusables()[0] },
        lastFocusable() { return this.focusables().slice(-1)[0] },
        nextFocusable() { return this.focusables()[this.nextFocusableIndex()] || this.firstFocusable() },
        prevFocusable() { return this.focusables()[this.prevFocusableIndex()] || this.lastFocusable() },
        nextFocusableIndex() { return (this.focusables().indexOf(document.activeElement) + 1) % (this.focusables().length + 1) },
        prevFocusableIndex() { return Math.max(0, this.focusables().indexOf(document.activeElement)) -1 },
    }"
    x-init="document.addEventListener('focusin', event => { if (! show && ! $el.contains(event.target)) opener = event.target });
    $watch('show', value => {
        if (value) {
            document.body.classList.add('overflow-y-hidden');
            {{ $attributes->has('focusable') ? 'setTimeout(() => firstFocusable().focus(), 100)' : '' }}
        } else {
            document.body.classList.remove('overflow-y-hidden');
            {{-- Closing gives focus back to the button that opened the dialog. Livewire switches that button off while
                 it tells the server the dialog closed, which drops focus again, so for two seconds focus is put back
                 whenever it is nowhere. Once the person has moved to something else it is left alone. --}}
            let tries = 0;
            const back = () => {
                if (show || ! opener || ! document.contains(opener)) return;
                const at = document.activeElement;
                if (at && at !== document.body && at !== opener && ! $el.contains(at)) return;
                if (at !== opener) opener.focus();
                if (tries++ < 20) setTimeout(back, 100);
            };
            setTimeout(back, 50);
        }
    })"
    x-on:close.stop="show = false"
    x-on:keydown.escape.window="show = false"
    x-on:keydown.tab.prevent="$event.shiftKey || nextFocusable().focus()"
    x-on:keydown.shift.tab.prevent="prevFocusable().focus()"
    x-show="show"
    id="{{ $id }}"
    class="jetstream-modal fixed inset-0 overflow-y-auto px-4 py-6 sm:px-0 z-[80]"
    style="display: none;"
>
    <div x-show="show" class="fixed inset-0 transform transition-all" x-on:click="show = false" x-transition:enter="ease-out duration-300"
                    x-transition:enter-start="opacity-0"
                    x-transition:enter-end="opacity-100"
                    x-transition:leave="ease-in duration-200"
                    x-transition:leave-start="opacity-100"
                    x-transition:leave-end="opacity-0">
        <div class="absolute inset-0" style="background: rgba(0, 0, 0, 0.55);"></div>
    </div>

    <div x-show="show" role="dialog" aria-modal="true" class="relative mb-6 overflow-hidden transform transition-all sm:mt-16 sm:w-full {{ $maxWidth }} sm:mx-auto"
                    style="background: var(--ix-panel); color: var(--ix-text); border: 1px solid var(--ix-rule-strong); border-radius: var(--ix-radius);"
                    x-transition:enter="ease-out duration-300"
                    x-transition:enter-start="opacity-0 translate-y-4 sm:translate-y-0 sm:scale-95"
                    x-transition:enter-end="opacity-100 translate-y-0 sm:scale-100"
                    x-transition:leave="ease-in duration-200"
                    x-transition:leave-start="opacity-100 translate-y-0 sm:scale-100"
                    x-transition:leave-end="opacity-0 translate-y-4 sm:translate-y-0 sm:scale-95">
        {{ $slot }}
    </div>
</div>
